-- Preserve drafts for the older consent-to-intake route too.
create policy legacy_draft_insert on public.onboarding_drafts for insert to authenticated
with check(exists(select 1 from public.clients c where c.id=client_id and c.profile_id=(select auth.uid()) and c.onboarding_status='pending_onboarding' and not exists(select 1 from public.onboarding_journeys j where j.client_id=c.id) and exists(select 1 from public.legal_consents l where l.client_id=c.id and l.consent_type='coaching_privacy_health' and l.accepted_at is not null)));
create policy legacy_draft_update on public.onboarding_drafts for update to authenticated
using(exists(select 1 from public.clients c where c.id=client_id and c.profile_id=(select auth.uid()) and c.onboarding_status='pending_onboarding' and not exists(select 1 from public.onboarding_journeys j where j.client_id=c.id) and exists(select 1 from public.legal_consents l where l.client_id=c.id and l.consent_type='coaching_privacy_health' and l.accepted_at is not null)))
with check(exists(select 1 from public.clients c where c.id=client_id and c.profile_id=(select auth.uid()) and c.onboarding_status='pending_onboarding' and not exists(select 1 from public.onboarding_journeys j where j.client_id=c.id) and exists(select 1 from public.legal_consents l where l.client_id=c.id and l.consent_type='coaching_privacy_health' and l.accepted_at is not null)));
